effect.shader:
const int MAX_TAPS = 48;

void main() {
    float rad = radians(angle);
    // Em pixels da COMPOSIÇÃO: `acEscalaDePixel` converte para o buffer, e a prévia
    // reduzida (o Auto da tela, o play) fica do tamanho da exportação (0.516.0).
    vec2 stride = vec2(cos(rad), sin(rad)) * (reach * acEscalaDePixel) * acTexelSize;

    int taps = clamp(int(quality + 0.5), 1, MAX_TAPS);
    if (taps == 1 || reach <= 0.0) {
        fragColor = texture(inputImg, acScreenNorm);
        return;
    }

    vec4 total = vec4(0.0);
    for (int i = 0; i < MAX_TAPS; i++) {
        if (i >= taps) break;
        float t = float(i) / float(taps - 1);
        // Centrado borra dos dois lados (parece fora de foco em movimento);
        // rastro puxa só para trás (parece velocidade com direção).
        float offset = trail ? -t : (t - 0.5);
        total += texture(inputImg, clamp(acScreenNorm + stride * offset, 0.0, 1.0));
    }

    fragColor = total / float(taps);
}
